def squash(s: str) -> str:
    if not s:
        return ""

    result = []
    n = len(s)
    i = 0
    while i < n:
        char = s[i]
        count = 1
        # Count the length of the current run of identical characters
        while i + 1 < n and s[i+1] == char:
            i += 1
            count += 1

        # Determine the escaped version of the character
        # Escaping is required for digits ('0'-'9') and backslash ('\')
        if char == '\\' or ('0' <= char <= '9'):
            esc_char = '\\' + char
        else:
            esc_char = char

        # Apply compression rule based on run length
        if count >= 3:
            result.append(str(count))
            result.append(esc_char)
        else:
            # Runs of length 1 or 2 are written as escaped char repeated
            result.append(esc_char * count)

        i += 1

    return "".join(result)
